        long discount = (Math.multiplyExact(total.minorUnits(), rate) + BASIS_POINTS_PER_WHOLE / 2) / BASIS_POINTS_PER_WHOLE;
        order.changeTotal(total.minus(new Money(discount, total.currency())));
