    private static final long BASIS_POINTS_PER_WHOLE = 10_000;

    /**
     * Converts text such as "12.5" or "0.01" into whole basis points (1250, 1).
     * At most two decimal places, from 0 to 100 percent. Anything else is refused.
     */
    static long toBasisPoints(String text) {
        String s = null == text ? "" : text.trim();
        long whole = 0;
        long fraction = 0;
        int fractionDigits = 0;
        int digits = 0;
        boolean afterDot = false;
        for (char c : s.toCharArray()) {
            if ('.' == c && !afterDot) {
                afterDot = true;
            } else if (c >= '0' && c <= '9') {
                digits++;
                int digit = c - '0';
                if (afterDot) {
                    if (fractionDigits == 2) {
                        throw invalidPercent(text);
                    }
                    fraction = fraction * 10 + digit;
                    fractionDigits++;
                } else {
                    whole = whole * 10 + digit;
                    if (whole > 100) {
                        throw invalidPercent(text);
                    }
                }
            } else {
                throw invalidPercent(text);
            }
        }
        if (digits == 0 || (afterDot && fractionDigits == 0)) {
            throw invalidPercent(text);
        }
        if (fractionDigits == 1) {
            fraction *= 10; // "12.5" is 50 hundredths, not 5
        }
        long rate = whole * 100 + fraction;
        if (rate > BASIS_POINTS_PER_WHOLE) {
            throw invalidPercent(text);
        }
        return rate;
    }

    private static ShopProblem invalidPercent(String text) {
        return new ShopProblem("invalid-percent", "Not a percentage from 0 to 100 with at most two decimals: " + text);
    }
